UML:TaggedValue.value:
**CDIF**
Definition ==========
:valueSchema: {"allOf": [{"properties": {"schema:hasPart": {"type": "array", "description": "For bundle/archive distributions (positively typed with schema:Collection in @type), describes the component files. Each component is typed as schema:MediaObject and may include CDIF data description extensions (cdifTabularData, cdifDataCube) to describe its internal structure.", "items": {"allOf": [{"type": "object", "properties": {"@id": {"type": "string", "description": "Identifier for this file, typically a hash-based anchor (e.g. '#abc123'). Used for cross-references from schema:about in metadata sidecar files."}, "@type": {"type": "array", "description": "Must include schema:MediaObject. Must NOT include schema:DataDownload since this file is not independently accessible. May include additional types for categorization.", "items": {"type": "string"}, "contains": {"const": "schema:MediaObject"}, "not": {"contains": {"const": "schema:DataDownload"}}, "minItems": 1}, "schema:name": {"type": "string", "description": "Filename of the component file within the archive."}, "schema:description": {"type": "string", "description": "Description of the file content. May include checksum information."}, "schema:encodingFormat": {"type": "array", "description": "MIME type(s) for this file.", "items": {"type": "string"}}, "schema:additionalType": {"type": "array", "description": "Domain-specific type classification for this member file: what KIND of thing it is, beyond its MIME type. The @type above says only that it is a schema:MediaObject, and using @type to carry a domain classification conflates \"what this node is\" with \"what it is about\". A plain string is accepted; a schema:DefinedTerm carrying schema:inDefinedTermSet is preferred where the value comes from a controlled vocabulary.", "items": {"$ref": "bb:cdifDataType/cdifConceptOrTermOrString/schema.yaml"}}, "schema:size": {"type": "object", "description": "File size as a QuantitativeValue.", "properties": {"@type": {"type": "array", "items": {"type": "string"}, "contains": {"const": "schema:QuantitativeValue"}, "minItems": 1}, "schema:value": {"type": "number", "description": "Numeric size value."}, "schema:unitText": {"type": "string", "description": "Unit of measure for size (e.g. 'byte')."}}}, "schema:about": {"type": "array", "description": "For metadata sidecar files, references the data file this metadata describes.", "items": {"type": "object", "required": ["@id"], "additionalProperties": false, "properties": {"@id": {"type": "string", "description": "Reference to the @id of the data file described by this sidecar."}}}}, "spdx:checksum": {"type": "object", "description": "Checksum for integrity verification of this component file.", "properties": {"@type": {"type": "array", "items": {"type": "string"}, "contains": {"const": "spdx:Checksum"}, "minItems": 1}, "spdx:algorithm": {"type": "string"}, "spdx:checksumValue": {"type": "string"}}, "required": ["@type", "spdx:algorithm", "spdx:checksumValue"]}}, "required": ["@type", "schema:name", "schema:encodingFormat"]}, {"anyOf": [{"$ref": "bb:cdifDataType/cdifDataCube/schema.yaml"}, {"$ref": "bb:cdifDataType/cdifTabularData/schema.yaml"}, {}]}]}}}}, {"if": {"properties": {"@type": {"type": "array", "contains": {"const": "schema:Collection"}}}, "required": ["@type"]}, "then": {"required": ["schema:hasPart"]}}]}
